SET NOCOUNT ON;
CREATE TABLE #r (id varchar(40), res nvarchar(400));
BEGIN TRY INSERT #r SELECT 'dec-long', CONCAT(a,'') FROM OPENJSON(N'{"a":0.12500000000000000000000000000000000001}') WITH (a decimal(18,2)); END TRY BEGIN CATCH INSERT #r VALUES('dec-long','ERR '+ERROR_MESSAGE()) END CATCH
BEGIN TRY INSERT #r SELECT 'dec-38', CONCAT(a,'') FROM OPENJSON(N'{"a":0.1250000000000000000000000000000000000}') WITH (a decimal(18,2)); END TRY BEGIN CATCH INSERT #r VALUES('dec-38','ERR '+ERROR_MESSAGE()) END CATCH
BEGIN TRY INSERT #r SELECT 'dec-int', CONCAT(a,'') FROM OPENJSON(N'{"a":5}') WITH (a decimal(18,2)); END TRY BEGIN CATCH INSERT #r VALUES('dec-int','ERR '+ERROR_MESSAGE()) END CATCH
BEGIN TRY INSERT #r SELECT 'date-y1', CONCAT(a,'') FROM OPENJSON(N'{"a":"0001-01-01"}') WITH (a date); END TRY BEGIN CATCH INSERT #r VALUES('date-y1','ERR '+ERROR_MESSAGE()) END CATCH
BEGIN TRY INSERT #r SELECT 'int-negzero-str', CONCAT(a,'') FROM OPENJSON(N'{"a":-12}') WITH (a int); END TRY BEGIN CATCH INSERT #r VALUES('int-negzero-str','ERR '+ERROR_MESSAGE()) END CATCH
BEGIN TRY INSERT #r SELECT 'int-min', CONCAT(a,'') FROM OPENJSON(N'{"a":-2147483648}') WITH (a int); END TRY BEGIN CATCH INSERT #r VALUES('int-min','ERR '+ERROR_MESSAGE()) END CATCH
BEGIN TRY INSERT #r SELECT 'int-dot0', CONCAT(a,'') FROM OPENJSON(N'{"a":12.0}') WITH (a int); END TRY BEGIN CATCH INSERT #r VALUES('int-dot0','ERR '+ERROR_MESSAGE()) END CATCH
BEGIN TRY INSERT #r SELECT 'quoted-path', CONCAT(a,'') FROM OPENJSON(N'{"a":1}') WITH (a int '$."a"'); END TRY BEGIN CATCH INSERT #r VALUES('quoted-path','ERR '+ERROR_MESSAGE()) END CATCH
BEGIN TRY INSERT #r SELECT 'lax-explicit', CONCAT(a,'') FROM OPENJSON(N'{"a":1}') WITH (a int 'lax $.a'); END TRY BEGIN CATCH INSERT #r VALUES('lax-explicit','ERR '+ERROR_MESSAGE()) END CATCH
BEGIN TRY INSERT #r SELECT 'colname-case', CONCAT(A,'') FROM OPENJSON(N'{"a":1,"A":2}') WITH (A int); END TRY BEGIN CATCH INSERT #r VALUES('colname-case','ERR '+ERROR_MESSAGE()) END CATCH
BEGIN TRY INSERT #r SELECT 'bracket-col', CONCAT([My Col],'') FROM OPENJSON(N'{"My Col":1}') WITH ([My Col] int); END TRY BEGIN CATCH INSERT #r VALUES('bracket-col','ERR '+ERROR_MESSAGE()) END CATCH
SELECT id + ' => ' + ISNULL(res,'<NULL>') FROM #r;
